use std::{env,fs};use wasmc_data_profile_component::{Lib,wasmtime};use wasmc_data_profile_component::wasmc::data_core::types::{Field,DataType,Column,BatchSnapshot};use wasmc_data_profile_component::exports::wasmc::data_profile::profile::Summary;use wasmtime::{Engine,Store};use wasmtime::component::{Component,Linker};
fn main(){let args:Vec<_>=env::args().collect();let engine=Engine::default();let component=Component::new(&engine,fs::read(&args[1]).unwrap()).unwrap();let mut store=Store::new(&engine,());let lib=Lib::instantiate(&mut store,&component,&Linker::new(&engine)).unwrap();let profile=lib.wasmc_data_profile_profile();for n in [8,1048577,3145728,11]{let batch=BatchSnapshot{rows:1,fields:vec![Field{name:"value".into(),data_type:DataType::Utf8,nullable:false}],columns:vec![Column::Utf8Column(vec![Some("x".repeat(n))])]};let result=profile.call_describe(&mut store,&batch,&[0]).unwrap().unwrap();assert_eq!(result.len(),1);match result[0].summary{Summary::Utf8(x)=>{assert_eq!(x.non_null,1);assert_eq!(x.min_length,Some(n as u32));assert_eq!(x.max_length,Some(n as u32));},_=>panic!("unexpected summary")};}println!("{{\"accepted\":true,\"engine\":\"wasmtime-component\",\"largest_input\":3145728,\"same_instance_new_inputs\":true}}");}
